import {AXES} from './context.js';
import {describeAxisPosition,renderAxisSummary} from './axis-presentation.js';
import {COUNTRY_AXES,rankCountries,countryCatalog} from './countries.js';
import {questionConcept} from './question-audit.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const IDEOLOGY_COPY={
 socialdemocrata:{name:'Socialdemocracia',phrase:'Prefiero una economía con iniciativa privada, un Estado activo y derechos sociales que reduzcan las desigualdades.'},
 liberal:{name:'Liberalismo de mercado',phrase:'Prefiero más libertad para emprender, competir y elegir, con impuestos contenidos y apertura a los cambios sociales.'},
 conservadora:{name:'Conservadurismo de mercado',phrase:'Prefiero una economía con iniciativa privada y cambios prudentes que preserven las tradiciones sociales.'},
 socialconservadora:{name:'Conservadurismo social',phrase:'Prefiero protección social y un Estado presente en la economía, junto con valores familiares y sociales tradicionales.'},
 mixta:{name:'Pragmatismo',phrase:'Prefiero combinar mercado, regulación y políticas sociales según cada problema, sin una inclinación marcada hacia uno de esos polos.'}
};
export function ideologyDescription(model){return {...model,...IDEOLOGY_COPY[model.id]}}
export function percentageBadge(score,label='afinidad'){return `<div class="percentage-badge"><strong>${score}%</strong><span>${esc(label)}</span></div>`}
export function differenceCard(x){const a=AXES[x.axis],reference=describeAxisPosition(a,x.reference);return `<article class="axis-comparison">${renderAxisSummary(a,x.user,{inlineResult:true})}<p class="comparison-reference">Referencia: <strong>${esc(reference.label)}</strong><span class="sr-only">. ${esc(a.name)}: vos ${x.user}, referencia ${x.reference}</span></p>${x.count?`<p class="small">${x.count} preguntas documentadas · resumen parcial de esas mismas respuestas.</p>`:''}</article>`}
export function renderDifferences(entity,details){return `<p>Comparación con <strong>${esc(entity.name)}</strong>. Tu opción aparece resaltada con su porcentaje. Se resumen únicamente las mismas preguntas documentadas en ambos lados; el índice se calcula por respuesta.</p><h3>En qué coincidís más</h3><div class="difference-grid">${details.near.length?details.near.map(differenceCard).join(''):'<p>No hay coincidencias direccionales documentadas en estas respuestas.</p>'}</div><h3>En qué te diferenciás más</h3><div class="difference-grid">${details.far.length?details.far.map(differenceCard).join(''):'<p>No hay contradicciones direccionales documentadas; esto no convierte los vacíos en coincidencias.</p>'}</div><a href="#comparar/${entity.id}">Ver respuestas y fuentes</a>`}
export function distinctivePriorities(profile,entities,{questions=[],answers={}}={}){
 const median=xs=>{const a=[...xs].sort((a,b)=>a-b),m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2};
 const partial=axis=>{const groups=new Map();for(const q of questions.filter(q=>q.axis===axis)){const id=q.id.replace(/v3$/,''),known=entities.map(e=>e.positions?.[id]).filter(x=>x?.status==='documented'&&Number.isInteger(x.position)).map(x=>x.position);if(known.length<3||!Number.isInteger(answers[q.id]))continue;const key=questionConcept(q);if(!groups.has(key))groups.set(key,[]);groups.get(key).push({user:(answers[q.id]-2)*q.direction,reference:(median(known)-2)*q.direction})}if(!groups.size)return null;const means=[...groups.values()].map(xs=>({user:xs.reduce((s,x)=>s+x.user,0)/xs.length,reference:xs.reduce((s,x)=>s+x.reference,0)/xs.length}));return {user:Math.round(50+25*means.reduce((s,x)=>s+x.user,0)/means.length),reference:50+25*means.reduce((s,x)=>s+x.reference,0)/means.length}};
 const items=AXES.map((axis,i)=>{const x=partial(i);return x?{axis:i,...x,gap:Math.round(Math.abs(x.user-x.reference)*10)/10}:null}).filter(Boolean);
 if(!items.length)return '<p>Falta evidencia de al menos tres referentes sobre las mismas preguntas para construir esta comparación.</p>';
 const unusual=[...items].sort((a,b)=>b.gap-a.gap||a.axis-b.axis)[0],typical=[...items].sort((a,b)=>a.gap-b.gap||a.axis-b.axis)[0];
 return `<div class="distinctive-grid">${[[unusual,'Tu posición más distinta'],[typical,'Tu punto más cercano']].map(([x,label])=>`<article><p class="small">${label}</p>${renderAxisSummary(AXES[x.axis],x.user)}<p class="small">${x.gap===0?'Coincidís con la mediana.':`A ${x.gap} puntos de la mediana de las referencias.`} Solo preguntas compartidas con tres o más referentes; no es la mediana de la población.</p></article>`).join('')}</div>`;
}
export function renderCountryResults(profile,mode='current'){
 const ranked=rankCountries(profile,mode),catalog=countryCatalog(mode),scores=new Map(ranked.map(x=>[x.entity.id,x.score]));
 const card=x=>'<article class="country-match">'+(mode==='current'?'<img class="country-flag-image" src="flags/'+x.entity.id+'.svg" alt="Bandera de '+esc(x.entity.name)+'" width="110" height="75">':'<span class="country-era" aria-hidden="true">'+esc(x.entity.period.match(/\d{4}/)?.[0]||'')+'</span>')+'<div><h3>'+esc(x.entity.name)+'</h3><p>'+esc(x.entity.period)+'</p></div>'+percentageBadge(x.score)+'</article>';
 const tied=ranked.filter(x=>x.score===ranked[0]?.score).length;
 return '<p class="small country-coverage">'+ranked.length+' perfiles comparables de '+catalog.length+' entradas. Afinidad constitucional sobre Economía, Instituciones y Religión. Compara documentos fechados; no describe a sus habitantes ni al gobierno actual y no presupone que el texto siga vigente.</p>'+(ranked.length?card(ranked[0]):'<p>No hay perfiles comparables.</p>')+(tied>1?'<p class="small">'+tied+' países comparten el porcentaje más alto. Orden alfabético dentro del mismo porcentaje.</p>':'')+'<h3>También cerca de vos</h3><div class="country-nearby">'+ranked.slice(1,4).map(card).join('')+'</div><details><summary>Ver los '+catalog.length+' países y sus fuentes</summary><label>Buscar país<input id="country-search" type="search" placeholder="Nombre del país" autocomplete="off"></label><ul class="country-catalog">'+catalog.map(c=>'<li data-country-search="'+esc(c.name.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,''))+'"><div><span>'+esc(mode==='current'?c.flag||'':'')+' '+esc(c.name)+'</span><p class="small">'+esc(c.period||'')+'</p><p class="small">'+c.notes.map(esc).join(' ')+'</p><p class="small">'+COUNTRY_AXES.map(i=>esc(AXES[i].name)+': '+c.profile[i]).join(' · ')+'</p><p class="small">'+c.sources.map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a>').join(' · ')+(c.subsequentlyAmended?' · El proveedor indica reformas posteriores no incorporadas.':'')+'</p></div><strong>'+scores.get(c.id)+'%</strong></li>').join('')+'</ul><p id="country-empty" hidden>No hay países con ese nombre en este catálogo.</p></details><details><summary>Fuentes y criterio de afinidad</summary><p>Rúbrica documental editorial en tres ejes. Economía: 0 planificación y propiedad social, 25 dirección o provisión estatal, 50 propiedad con función social o esquema mixto, 75 protección de propiedad privada. Instituciones: 25 contrapesos, 50 Ejecutivo reforzado, 75 autoridad política dirigente, 100 soberano sin responsabilidad parlamentaria. Religión: 0 laicidad o no establecimiento, 25 garantía de libertad religiosa, 75 reconocimiento confesional especial, 100 religión estatal o jefatura confesional.</p><p>Afinidad = 100 menos la distancia absoluta media en esos tres ejes. Los nueve ejes no comparados permanecen sin puntaje. Las cifras son interpretaciones propias de disposiciones seleccionadas, no índices empíricos ni porcentajes publicados por las fuentes. Distintos textos pueden obtener el mismo perfil y empatar.</p><p>Las versiones enlazadas no constituyen una auditoría de vigencia jurídica en 2026. Esto importa especialmente en países con textos suspendidos, transiciones o conflictos. El período identifica el documento, no toda la historia ni todas las políticas del país. Las garantías escritas no prueban su aplicación real.</p><p>Catálogo actual: 193 miembros y dos observadores de la ONU. Nombres y banderas: <a href="https://github.com/mledoze/countries" target="_blank" rel="noopener noreferrer">mledoze/countries · ODbL</a>. No incluye todos los Estados con reconocimiento disputado. Referencias constitucionales: <a href="https://www.constituteproject.org/content/data" target="_blank" rel="noopener noreferrer">Constitute / Comparative Constitutions Project</a>, complementadas con fuentes oficiales identificadas en el catálogo. Selección histórica de documentos, sin pretensión de cubrir toda la historia.</p></details>';
}
